text:
{
  "claims": [
    {
      "anchor": "With the default policy of fsync every second, Redis can lose about one second of writes in a disaster",
      "claim_text": "With the default fsync-every-second policy, Redis can lose about one second of writes in a disaster.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "entails"},
        {"sid": "P5.S4", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Both passages state losing one second of writes with everysec default."
    },
    {
      "anchor": "the fsync itself is done on a background thread",
      "claim_text": "fsync is performed using a background thread.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S2 explicitly says fsync is performed using a background thread."
    },
    {
      "anchor": "everysec has been the default since Redis 2.4",
      "claim_text": "The everysec policy has been the default since Redis 2.4.",
      "kind": "version",
      "sure": false,
      "evidence": [
        {"sid": "P5.S4", "rel": "entails"},
        {"sid": "P6.S0", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "2.4", "op": ">=", "right": "2.4"},
      "reasoning": "P5.S4 says everysec likely as fast as snapshotting since 2.4; P6.S0 says everysec is default, but no sentence says default since 2.4."
    },
    {
      "anchor": "With appendfsync always, Redis still performs a separate fsync for every client write even when many writes arrive in parallel",
      "claim_text": "With appendfsync always, Redis performs a separate fsync for every client write even when many writes arrive in parallel.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P5.S2", "rel": "refutes"},
        {"sid": "P6.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passages say group commit batches parallel writes into a single fsync, contradicting separate fsync per write."
    },
    {
      "anchor": "RDB snapshots, by contrast, are usually taken every five minutes or more",
      "claim_text": "RDB snapshots are usually taken every five minutes or more.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S2 states you'll usually create an RDB snapshot every five minutes or more."
    },
    {
      "anchor": "if you can live with a few minutes of data loss the docs say RDB alone is fine",
      "claim_text": "If you can live with a few minutes of data loss, RDB alone is fine.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P3.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P3.S0 directly states this condition and recommendation."
    },
    {
      "anchor": "With fsync disabled, AOF should be exactly as fast as RDB even under high load",
      "claim_text": "With fsync disabled, AOF should be exactly as fast as RDB even under high load.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S2 states this exactly."
    },
    {
      "anchor": "RDB can still give stronger guarantees about maximum latency under a huge write load",
      "claim_text": "RDB can provide stronger guarantees about maximum latency under a huge write load.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S3", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S3 states RDB provides more guarantees about maximum latency under huge write load."
    },
    {
      "anchor": "If the AOF ends with a truncated command, recent Redis versions refuse to start by default",
      "claim_text": "If the AOF ends with a truncated command, recent Redis versions refuse to start by default.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S2", "rel": "refutes"},
        {"sid": "P8.S0", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passages say recent versions load the AOF discarding the bad command, and default is to continue."
    },
    {
      "anchor": "the truncated file still holds a consistent point-in-time version of the dataset",
      "claim_text": "A truncated AOF file still holds a consistent point-in-time version of the dataset.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P7.S1 states the AOF still contains consistent data representing a point-in-time version."
    },
    {
      "anchor": "with the default policy, may be up to one second old",
      "claim_text": "With the default policy, the consistent point-in-time version may be up to one second old.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P7.S1 states the point-in-time version may be old up to one second with default fsync policy."
    }
  ]
}
